Psize=1;
run;


%needleplot4snpsdiffzscores(
diffzscore_gwas=D.hgi_b1_vs_b2,
gwas1_z=gwas1_z,
gwas2_z=gwas2_z,
snp_var=rsid,
snps=&names,
diffzscore_p_var=pval,
gwas1pvar=gwas1_p,
gwas2pvar=gwas2_p
);

*Get target GWAS SNPs P values;
data GWAS_SNPs;
input rsID $20.;
cards;
12:113357193:G:A
17:44219831:T:A
19:10427721:T:A
rs10490770
rs11919389
